const target = document.createElement("button");
const onClick = () => console.log("click");
const onKeydown = event => console.log(event.key);
// Implement attachListeners before using this cleanup contract.
const cleanup = attachListeners(target, onClick, onKeydown);
cleanup();

Correct Answer:
function attachListeners(target, onClick, onKeydown) {
  const controller = new AbortController();
  target.addEventListener("click", onClick, { signal: controller.signal });
  target.addEventListener("keydown", onKeydown, { signal: controller.signal });
  return () => controller.abort();
}
